/* ======================= ROUTER ======================= */
const ROUTES = []; // [regex, handler(params), navId?]
function route(pattern, fn) { const keys = []; const re = new RegExp('^' + pattern.replace(/:(\w+)/g, (_, k) => { keys.push(k); return '([^/]+)'; }) + '$'); ROUTES.push({ re, keys, fn, pattern }); }
let pageMount = null;
function go(r) { if (location.hash !== '#' + r) location.hash = r; else render(); }
function render() {
  if (typeof recompute === 'function') recompute();
  { const pth = (location.hash.slice(1) || '/overview').split('?')[0]; const i = RECENT.indexOf(pth); if (i >= 0) RECENT.splice(i, 1); RECENT.unshift(pth); RECENT.length = Math.min(RECENT.length, 8); }
  S.route = (location.hash.replace(/^#/, '') || '/overview'); if (!S.route.startsWith('/')) S.route = '/overview';
  closeOverlays(); const w = document.getElementById('work');
  const navId = activeNavId(S.route.split('?')[0]); const nav = NAVIDX[navId];
  let out = null; const path = S.route.split('?')[0];
  const exact = ROUTES.find(rt => !rt.keys.length && rt.re.test(path));
  if (exact) out = { rt: exact, params: {} };
  else if (!routeNav[path]) for (const rt of ROUTES) { const m = path.match(rt.re); if (m) { const params = {}; rt.keys.forEach((k, i) => params[k] = decodeURIComponent(m[i + 1])); out = { rt, params }; break; } }
  let html, mount;
  const perm = S.route === '/ia' ? 'iamap.view' : path.startsWith('/p/') ? null : nav ? nav.p : null;
  if (!can(perm) && S.route !== '/ia') { html = `<div class="page">${crumbs([[BRAND.name, '/overview'], [t(navId), S.route]])}<div class="panel" style="margin-top:12px">${stateBlock('noperm')}<div style="text-align:center;padding-bottom:20px" class="muted mono">required: ${esc(perm)} · route: ${esc(S.route)}</div></div></div>`; }
  else if (path.startsWith('/p/') && typeof portalEmpty === 'function' && WS[wsOf(path)] && !me(wsOf(path))) { const res = portalEmpty(wsOf(path)); html = res.html; mount = res.mount; }
  else if (out) { try { const res = out.rt.fn(out.params); html = res.html; mount = res.mount; } catch (e) { console.warn('route', path, e); html = `<div class="page"><div class="panel" style="margin-top:12px">${stateBlock('empty')}</div></div>`; mount = null; } }
  else if (nav && nav.r === path) { const res = PAGES.placeholder(navId); html = res.html; mount = res.mount; }
  else { html = `<div class="page">${stateBlock('noresult', { title: '404', desc: 'Route tidak ditemukan: ' + S.route })}</div>`; }
  w.innerHTML = html; w.scrollTop = 0; pageMount = mount; if (mount) mount();
  renderSide(); renderTop(); document.getElementById('app').classList.remove('drawer-open');
  document.title = (path.startsWith('/p/') ? wsLabel(wsOf()) : (nav ? t(navId) + ' · ' : '') + BRAND.name + ' ' + t('control_center'));
}
function rerender() { const w = document.getElementById('work'); const st = w.scrollTop; render(); w.scrollTop = st; }

/* ======================= OVERLAYS ======================= */
const ovl = () => document.getElementById('ovl');
let lastFocus = null;
function closeOverlays() { const o = ovl(); if (o && o.innerHTML) { o.innerHTML = ''; if (lastFocus && document.contains(lastFocus)) lastFocus.focus(); } hideTip(); }
function openLayer(html, focusSel) { lastFocus = document.activeElement; ovl().innerHTML = html; const f = ovl().querySelector(focusSel || 'input,textarea,select,button:not([data-act="close"])'); if (f) setTimeout(() => f.focus(), 20); }
function modal({ title, body, foot, wide }) { openLayer(`<div class="scrim" data-act="close"></div><div class="modal ${wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-h"><h3>${esc(title)}</h3><button class="iconbtn" data-act="close" aria-label="${t('close')}">${ic('x')}</button></div><div class="modal-b">${body}</div>${foot ? `<div class="modal-f">${foot}</div>` : ''}</div>`); }
function drawer({ title, sub, body, foot }) { openLayer(`<div class="scrim" data-act="close"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-h"><div style="flex:1;min-width:0"><h3>${esc(title)}</h3>${sub ? `<div class="muted" style="font-size:12px">${sub}</div>` : ''}</div><button class="iconbtn" data-act="close" aria-label="${t('close')}">${ic('x')}</button></div><div class="modal-b">${body}</div>${foot ? `<div class="modal-f">${foot}</div>` : ''}</aside>`); }
let confirmCb = null;
function confirmAction({ title, desc, tone = 'primary', label, reason = true, resource, onOk }) {
  if (S.ux === 'offline') { toast('warn', L3(['Aksi ditunda', 'Action paused', 'تم إيقاف الإجراء']), t('offline_b')); return; }
  confirmCb = onOk;
  modal({ title, body: `${desc ? `<p style="margin:0 0 12px;color:var(--ink-2)">${desc}</p>` : ''}${resource ? `<div class="chip mono" style="margin-bottom:12px">${esc(resource)}</div>` : ''}${reason ? `<div class="field"><label for="cf-reason">${t('reason')} *</label><textarea id="cf-reason" placeholder="${esc(t('reason_req'))}"></textarea><span class="hint" id="cf-hint">${t('reason_req')}</span></div>` : ''}<div class="auditbox">${ic('history')}<div><b>${esc(L3(['Jejak audit', 'Audit trail', 'سجل التدقيق']))}</b><br>${esc(t('audit_note'))}<br><span class="mono">actor: Admin Pusat (${esc(ROLES[S.role].label)}) · source: Web · ${esc(fDT(nowTs()))}</span></div></div>`,
    foot: `<button class="btn" data-act="close">${t('cancel')}</button><button class="btn ${tone}" data-act="confirm-ok" data-need="${reason ? 1 : 0}">${esc(label || t('confirm'))}</button>` });
}
function toast(tone, title, sub, link) { const id = 'ts' + Math.random().toString(36).slice(2, 7); const el = document.createElement('div'); el.className = 'toast'; el.id = id; el.setAttribute('role', tone === 'bad' ? 'alert' : 'status'); el.innerHTML = `<span class="tic ${tone}">${ic(tone === 'ok' ? 'check' : tone === 'bad' ? 'alert' : tone === 'warn' ? 'alert' : 'info', 'sm')}</span><div class="tb"><b>${esc(title)}</b>${sub ? `<div class="ts">${esc(sub)}</div>` : ''}${link ? `<a href="#${link}">${esc(t('open_detail'))} →</a>` : ''}</div><button data-act="toast-x" aria-label="${t('close')}" style="color:inherit;opacity:.6">${ic('x', 'sm')}</button>`; const box = document.getElementById('toasts'); box.appendChild(el); while (box.children.length > 4) box.firstElementChild.remove(); setTimeout(() => el.remove(), 6500); }
function popAt(anchor, html, align) { lastFocus = document.activeElement; const r = anchor.getBoundingClientRect(); const rtl = document.documentElement.dir === 'rtl'; ovl().innerHTML = `<div class="scrim" style="background:transparent" data-act="close"></div><div class="pop" role="menu" id="pop">${html}</div>`; const p = document.getElementById('pop'); const w = p.offsetWidth; let left = (align === 'start') !== rtl ? r.left : r.right - w; left = Math.max(8, Math.min(left, innerWidth - w - 8)); p.style.left = left + 'px'; const top = r.bottom + 6; p.style.top = Math.min(top, innerHeight - p.offsetHeight - 8) + 'px'; const f = p.querySelector('button,input'); if (f) f.focus(); }

/* tooltip & chart tip */
let tipEl = null;
function showTip(el, text, chart) { hideTip(); tipEl = document.createElement('div'); tipEl.className = chart ? 'ctip' : 'tip'; tipEl.textContent = text; document.body.appendChild(tipEl); const r = el.getBoundingClientRect(); const rtl = document.documentElement.dir === 'rtl'; if (el.closest('.app.collapsed .side') && !chart) { tipEl.style.top = (r.top + r.height / 2 - tipEl.offsetHeight / 2) + 'px'; tipEl.style.left = rtl ? (r.left - tipEl.offsetWidth - 8) + 'px' : (r.right + 8) + 'px'; } else { tipEl.style.top = Math.max(4, r.top - tipEl.offsetHeight - 6) + 'px'; tipEl.style.left = Math.max(4, Math.min(innerWidth - tipEl.offsetWidth - 4, r.left + r.width / 2 - tipEl.offsetWidth / 2)) + 'px'; } }
function hideTip() { if (tipEl) { tipEl.remove(); tipEl = null; } const f = document.getElementById('flyout'); if (f && !f.matches(':hover')) f.remove(); }
function showFly(btn) { const m = NAVIDX[btn.dataset.fly]; hideTip(); const r = btn.getBoundingClientRect(); const rtl = document.documentElement.dir === 'rtl'; const act = activeNavId(S.route); const el = document.createElement('div'); el.className = 'flyout'; el.id = 'flyout'; el.setAttribute('role', 'menu'); el.innerHTML = `<h6>${esc(t(m.id))}</h6>${m.kids.map(k => `<a class="nav-item ${k.id === act ? 'active' : ''}" href="#${k.r}" role="menuitem"><span class="lbl">${esc(t(k.id))}</span>${navBadge(k)}</a>`).join('')}`; document.body.appendChild(el); el.style.top = Math.min(r.top, innerHeight - el.offsetHeight - 8) + 'px'; el.style.left = rtl ? (r.left - el.offsetWidth - 6) + 'px' : (r.right + 6) + 'px'; el.addEventListener('mouseleave', () => el.remove()); el.addEventListener('click', () => el.remove()); }

/* ======================= TABLE ENGINE ======================= */
const TBL = {};
function defTable(id, cfg) { const prev = TBL[id]; TBL[id] = Object.assign({ q: '', page: 1, size: 10, sel: new Set(), hidden: new Set(), fval: 'all', sortK: null, sortDir: 1 }, prev ? { q: prev.q, page: prev.page, size: prev.size, sel: prev.sel, hidden: prev.hidden, fval: prev.fval, sortK: prev.sortK, sortDir: prev.sortDir } : {}, cfg); return `<div id="tb-${id}">${tableHTML(id)}</div>`; }
function tblRows(id) { const T = TBL[id]; let rows = T.rows(); if (T.filters && T.fval !== 'all') { const f = T.filters.find(x => x.v === T.fval); if (f) rows = rows.filter(f.fn); } if (T.q) { const q = T.q.toLowerCase(); rows = rows.filter(r => T.search(r).toLowerCase().includes(q)); } if (T.sortK) { const c = T.cols.find(c => c.k === T.sortK); const sv = c.sv || (r => r[c.k]); rows = rows.slice().sort((a, b) => { const x = sv(a), y = sv(b); return (x > y ? 1 : x < y ? -1 : 0) * T.sortDir; }); } return rows; }
function tableHTML(id) {
  const T = TBL[id]; const all = T.rows(); const rows = tblRows(id); const pages = Math.max(1, Math.ceil(rows.length / T.size)); if (T.page > pages) T.page = pages; const slice = rows.slice((T.page - 1) * T.size, T.page * T.size); const cols = T.cols.filter(c => !T.hidden.has(c.k));
  const fcount = f => f.v === 'all' ? all.length : all.filter(f.fn).length;
  let h = `<div class="toolbar">${T.search ? `<label class="input">${ic('search', 'sm')}<span class="sr">${t('search')}</span><input id="q-${id}" type="search" data-tblq="${id}" value="${esc(T.q)}" placeholder="${esc(T.placeholder || t('search'))}"></label>` : ''}
    ${T.filters ? `<div class="fchips" role="group" aria-label="Filter">${T.filters.map(f => `<button class="fchip" data-act="tbl-f" data-tbl="${id}" data-v="${f.v}" aria-pressed="${T.fval === f.v}">${esc(f.label)}<span class="n">${fcount(f)}</span></button>`).join('')}</div>` : ''}
    <span style="flex:1"></span>${T.moreFilters ? `<button class="btn sm" data-act="more-filter" data-tbl="${id}">${ic('funnel', 'sm')}${t('filters_more')}</button>` : ''}
    <button class="btn sm" data-act="tbl-cols" data-tbl="${id}" aria-haspopup="menu">${ic('columns', 'sm')}${t('columns')}</button>${T.exportable !== false ? `<button class="btn sm ghost" data-act="export" data-what="${esc(T.name || id)}">${ic('download', 'sm')}<span class="desk-only">Export</span></button>` : ''}</div>`;
  if (T.sel.size && T.bulk) h += `<div class="bulkbar" role="status"><b>${T.sel.size} ${t('selected')}</b>${T.bulk.map(b => `<button class="btn sm" data-act="bulk" data-tbl="${id}" data-b="${b.k}">${esc(b.label)}</button>`).join('')}<span style="flex:1"></span><button class="btn sm ghost" data-act="tbl-clear" data-tbl="${id}">${t('clear')}</button></div>`;
  let body;
  if (S.ux === 'loading') body = skel(6); else if (S.ux === 'error') body = stateBlock('error'); else if (S.ux === 'empty' || !all.length) body = stateBlock('empty'); else if (!rows.length) body = stateBlock('noresult', { tbl: id });
  else {
    const allSel = slice.every(r => T.sel.has(r.id));
    body = `<div class="tbl-wrap ${T.card ? 'cardable' : ''}"><table class="t"><thead><tr>${T.bulk ? `<th class="cb"><input type="checkbox" aria-label="Pilih semua" data-act="tbl-selall" data-tbl="${id}" ${allSel ? 'checked' : ''}></th>` : ''}${cols.map(c => `<th class="${c.cls || ''}" ${T.sortK === c.k ? `aria-sort="${T.sortDir > 0 ? 'ascending' : 'descending'}"` : ''} scope="col">${c.sort === false ? esc(c.label) : `<button class="sortbtn" data-act="tbl-sort" data-tbl="${id}" data-k="${c.k}">${esc(c.label)}${ic('sort', 'sm')}</button>`}</th>`).join('')}</tr></thead><tbody>
    ${slice.map(r => `<tr data-row="${esc(r.id)}" class="${T.route || T.open ? 'clickable' : ''} ${T.sel.has(r.id) ? 'sel' : ''} ${typeof SB !== 'undefined' && SB.flash.has(r.id) ? 'flash' : ''}" ${T.route ? `data-href="${esc(T.route(r))}"` : T.open ? `data-open="${id}"` : ''}>${T.bulk ? `<td class="cb"><input type="checkbox" aria-label="Pilih ${esc(r.id)}" data-act="tbl-sel" data-tbl="${id}" data-id="${esc(r.id)}" ${T.sel.has(r.id) ? 'checked' : ''}></td>` : ''}${cols.map(c => `<td class="${c.cls || ''}">${c.render ? c.render(r) : esc(r[c.k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
    ${T.card ? `<div class="cards-m">${slice.map(r => T.open ? `<button class="mcard" data-act="res-open" data-tbl="${id}" data-id="${esc(r.id)}">${T.card(r)}</button>` : `<a class="mcard" href="#${esc(T.route ? T.route(r) : S.route)}" style="color:inherit;text-decoration:none">${T.card(r)}</a>`).join('')}</div>` : ''}`;
  }
  h += body;
  if (!['loading', 'error', 'empty'].includes(S.ux) && rows.length) {
    const from = (T.page - 1) * T.size + 1, to = Math.min(rows.length, T.page * T.size); const pl = []; for (let p = 1; p <= pages; p++) { if (p === 1 || p === pages || Math.abs(p - T.page) <= 1) pl.push(p); else if (pl[pl.length - 1] !== '…') pl.push('…'); }
    h += `<div class="pager"><span>${t('showing')} <b class="tnum">${from}–${to}</b> ${t('of')} <b class="tnum">${rows.length}</b></span><select class="select" data-act-change="tbl-size" data-tbl="${id}" aria-label="${t('per_page')}" id="ps-${id}">${[10, 20, 50].map(n => `<option value="${n}" ${T.size === n ? 'selected' : ''}>${n} / ${t('per_page').split(' ').pop()}</option>`).join('')}</select><span class="sp"></span><nav class="pg" aria-label="Pagination"><button data-act="tbl-pg" data-tbl="${id}" data-p="${T.page - 1}" ${T.page === 1 ? 'disabled' : ''} aria-label="${t('prev')}">${icd('chevL', 'sm')}</button>${pl.map(p => p === '…' ? '<span style="padding:0 4px">…</span>' : `<button data-act="tbl-pg" data-tbl="${id}" data-p="${p}" ${p === T.page ? 'aria-current="page"' : ''}>${p}</button>`).join('')}<button data-act="tbl-pg" data-tbl="${id}" data-p="${T.page + 1}" ${T.page === pages ? 'disabled' : ''} aria-label="${t('next')}">${icd('chevR', 'sm')}</button></nav></div>`;
  }
  return h;
}
function refreshTable(id, keepFocus) { const el = document.getElementById('tb-' + id); if (!el) return; const a = document.activeElement; const had = a && a.id; const pos = a && a.selectionStart; el.innerHTML = tableHTML(id); if (keepFocus && had) { const n = document.getElementById(had); if (n) { n.focus(); try { n.setSelectionRange(pos, pos); } catch (e) {} } } }

