function openSearch() { CMD = { q: '', scope: 'all', i: 0, items: [] }; lastFocus = document.activeElement; ovl().innerHTML = `<div class="scrim" data-act="close"></div><div class="cmd" role="dialog" aria-modal="true" aria-label="${esc(t('search'))}"><div class="cmd-in">${ic('search', 'lg')}<input id="cmdq" placeholder="${esc(t('search_ph'))}" autocomplete="off" role="combobox" aria-expanded="true" aria-controls="cmdres"><kbd>Esc</kbd></div><div class="cmd-scopes" role="tablist">${SCOPES.map(([k, l]) => `<button class="fchip" data-act="cmd-scope" data-v="${k}" aria-pressed="${k === 'all'}">${esc(DICT[l] ? t(l) : l)}</button>`).join('')}</div><div class="cmd-res" id="cmdres" role="listbox"></div><div class="cmd-f"><span><kbd>↑</kbd> <kbd>↓</kbd> ${L3(['navigasi', 'navigate', 'تنقل'])}</span><span><kbd>Enter</kbd> ${L3(['buka', 'open', 'فتح'])}</span><span><kbd>Tab</kbd> ${L3(['ganti tipe', 'switch type', 'تبديل النوع'])}</span><span style="margin-inline-start:auto">${mockmark()}</span></div></div>`; const q = document.getElementById('cmdq'); q.focus(); q.addEventListener('input', () => { CMD.q = q.value; CMD.i = 0; drawCmd(); }); q.addEventListener('keydown', cmdKey); drawCmd(); }
function hl(s, q) { if (!q) return esc(s); const i = s.toLowerCase().indexOf(q.toLowerCase()); if (i < 0) return esc(s); return esc(s.slice(0, i)) + '<mark>' + esc(s.slice(i, i + q.length)) + '</mark>' + esc(s.slice(i + q.length)); }
const RECENT = [];
function drawCmd() {
  const q = CMD.q.trim().toLowerCase(); let idx = searchIndex().filter(x => CMD.scope === 'all' || x.type === CMD.scope);
  if (q) idx = idx.filter(x => x.s.toLowerCase().includes(q)); else idx = CMD.scope === 'all' ? [...idx.filter(x => x.type === 'page').slice(0, 0), ...idx.filter(x => ['travel', 'booking', 'campaign'].includes(x.type)).slice(0, 0)] : idx;
  const box = document.getElementById('cmdres'); if (!box) return;
  if (!q && CMD.scope === 'all') { const rec = (RECENT.length ? RECENT.slice(0, 6) : ['/approval', '/omni/inbox', '/finance']).map(p => { const n = Object.values(NAVIDX).find(x => x.r === p); return [p, n ? n.i : 'history', n ? t(n.id) : p]; }); CMD.items = rec.map(r => ({ r: r[0] })); box.innerHTML = `<div class="cmd-g">${L3(['Baru dibuka', 'Recent', 'الأخيرة'])}</div>` + rec.map((r, i) => `<button class="cmd-i" role="option" aria-selected="${i === CMD.i}" data-act="cmd-go" data-r="${r[0]}"><span class="ico">${ic(r[1])}</span><span class="body"><b>${esc(r[2])}</b><span class="mono">${esc(r[0])}</span></span></button>`).join('') + `<div class="cmd-g">Tips</div><div style="padding:4px 10px 10px;font-size:12.5px;color:var(--ink-2)">${L3(['Ketik nama, ID (TRV-, BK-, PAY-, CMP-), kota, atau referensi gateway. Hasil dikelompokkan per tipe resource.', 'Type a name, ID (TRV-, BK-, PAY-, CMP-), city or gateway reference. Results are grouped by resource type.', 'اكتب اسماً أو معرّفاً أو مدينة أو مرجع بوابة. النتائج مجمعة حسب النوع.'])}</div>`; return; }
  const groups = {}; idx.forEach(x => (groups[x.type] = groups[x.type] || []).push(x)); CMD.items = [];
  let h = ''; SCOPES.forEach(([k, l]) => { if (k === 'all' || !groups[k]) return; const g = groups[k]; const lim = CMD.scope === 'all' ? 4 : 30; h += `<div class="cmd-g"><span>${esc(DICT[l] ? t(l) : l)}</span><span>${g.length}</span></div>`; g.slice(0, lim).forEach(x => { const i = CMD.items.length; CMD.items.push(x); h += `<button class="cmd-i" role="option" id="ci-${i}" aria-selected="${i === CMD.i}" data-act="cmd-go" data-r="${esc(x.r)}"><span class="ico">${ic(x.icon)}</span><span class="body"><b>${hl(x.title, CMD.q.trim())}</b><span>${hl(x.sub, CMD.q.trim())}</span></span>${icd('chevR', 'sm muted')}</button>`; }); });
  box.innerHTML = h || stateBlock('noresult');
}
function cmdKey(e) { if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); CMD.i = (CMD.i + (e.key === 'ArrowDown' ? 1 : -1) + CMD.items.length) % Math.max(1, CMD.items.length); drawCmd(); const el = document.querySelector('.cmd-i[aria-selected="true"]'); if (el) el.scrollIntoView({ block: 'nearest' }); } else if (e.key === 'Enter') { const it = CMD.items[CMD.i]; if (it) { closeOverlays(); go(it.r); } } else if (e.key === 'Tab') { e.preventDefault(); const ks = SCOPES.map(s => s[0]); CMD.scope = ks[(ks.indexOf(CMD.scope) + (e.shiftKey ? -1 : 1) + ks.length) % ks.length]; CMD.i = 0; document.querySelectorAll('[data-act="cmd-scope"]').forEach(b => b.setAttribute('aria-pressed', b.dataset.v === CMD.scope)); drawCmd(); } }

